import React,{useState,useEffect,useRef,Suspense,lazy,Component} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity,LayoutDashboard,Radio,Telescope,ScrollText,BookOpen,Plus,Wind,Sun,Zap,ArrowUpRight,Download,Play,Pause,Check,Copy,X,ChevronRight,RefreshCw,ShieldCheck,Menu,Globe,Power} from 'lucide-react';
import './style.css';
import {commandFields,validateCommandForm} from './command-form.js';
import {createCommandReceipts,requestCommandJson} from './command-receipts.js';
import {eventTime} from './event-time.js';
const Scene=lazy(()=>import('./Scene.jsx'));
const nav=[['dashboard','통합 대시보드',LayoutDashboard],['devices','RTU 디바이스',Radio],['lab','시험 시나리오',Telescope],['logs','이벤트 로그',ScrollText],['api','연동 가이드',BookOpen]];
const typeNames={wind:'풍력',solar:'태양광',hybrid:'복합'};
const fmt=(v,d=1)=>v==null?'—':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:d});
const time=v=>v?new Date(v).toLocaleString('ko-KR',{hour12:false}):'—';
const sum=(p,k)=>(p?.generators||[]).reduce((s,g)=>s+(Number(g[k])||0),0);
function token(){return sessionStorage.getItem('grid-token')||''}
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:{...(token()?{Authorization:'Bearer '+token()}:{}),...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)});if(r.status===401){window.dispatchEvent(new Event('auth-required'));throw Error('관리 API 토큰을 입력해 주세요.')}if(!r.ok){let m;try{m=(await r.json()).error}catch{}throw Error(m||`요청 실패 (${r.status})`)}return r.json()}
async function download(path,name){const r=await fetch('/api'+path,{headers:token()?{Authorization:'Bearer '+token()}: {}});if(!r.ok)throw Error(`다운로드 실패 (${r.status})`);const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function Field({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Num({label,value,onChange,...props}){return <Field label={label}><input type="number" step="any" value={value??''} onChange={e=>onChange(e.target.value===''?'':Number(e.target.value))} {...props}/></Field>}
function Button({children,kind='',...p}){return <button className={'button '+kind} {...p}>{children}</button>}
function Badge({children,good=false,bad=false}){return <span className={'badge '+(good?'good':bad?'bad':'')}>{children}</span>}
function Panel({title,eyebrow,action,children,className=''}){return <section className={'panel '+className}><div className="panel-head"><div>{eyebrow&&<div className="eyebrow">{eyebrow}</div>}<h2>{title}</h2></div>{action}</div>{children}</section>}
function EventTime({event}){const value=eventTime(event);return value?<time dateTime={value.utc} aria-label={`${value.text} KST (UTC+09:00) · 원본 UTC ${value.utc}`} title={'원본 UTC '+value.utc}>{value.text}</time>:'—'}
function Metric({label,value,unit,sub,icon:Icon=Activity}){return <div className="metric"><div className="metric-label">{label}<Icon size={16}/></div><div className="metric-value">{value}<span>{unit}</span></div><small>{sub}</small></div>}
class SceneBoundary extends Component{state={error:false};static getDerivedStateFromError(){return {error:true}}render(){return this.state.error?<div className="scene-fallback">3D를 표시할 수 없습니다. 발전·제어 기능은 계속 사용할 수 있습니다.</div>:this.props.children}}
function App(){
 const [state,setState]=useState(null),[selected,setSelected]=useState(''),[page,setPage]=useState(location.hash.slice(1)||'dashboard'),[register,setRegister]=useState(false),[auth,setAuth]=useState(false),[authValue,setAuthValue]=useState(''),[error,setError]=useState(''),[notice,setNotice]=useState(''),[live,setLive]=useState(false),[session,setSession]=useState(0),[busy,setBusy]=useState(0),[updatedAt,setUpdatedAt]=useState(0),[now,setNow]=useState(Date.now());
 const accept=s=>{setUpdatedAt(Date.now());setState(s);setSelected(id=>s.plants.some(p=>p.id===id)?id:(s.plants[0]?.id||''));};
 const [,redrawReceipts]=useState(0),receiptManager=useRef(null);if(!receiptManager.current)receiptManager.current=createCommandReceipts({request:(path,method,body)=>requestCommandJson(path,method,body,{getToken:token,onAuth:()=>setAuth(true)}),onChange:()=>redrawReceipts(n=>n+1),onState:accept,secrets:()=>[token()]});
 const sendCommand=(plant,body)=>{setNotice('');return receiptManager.current.send(plant,body)};
 useEffect(()=>{const t=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(t)},[]);
 useEffect(()=>{const h=()=>setPage(location.hash.slice(1)||'dashboard'),a=()=>setAuth(true);window.addEventListener('hashchange',h);window.addEventListener('auth-required',a);return()=>{window.removeEventListener('hashchange',h);window.removeEventListener('auth-required',a)}},[]);
 useEffect(()=>{let stop=false,controller=new AbortController(),timer;async function connect(){try{accept(await api('/state'));setError('');const r=await fetch('/api/events',{headers:token()?{Authorization:'Bearer '+token()}: {},signal:controller.signal});if(r.status===401){setAuth(true);return}if(!r.ok)throw Error('실시간 연결 실패');setLive(true);const reader=r.body.getReader(),decoder=new TextDecoder();let buf='';while(!stop){const {value,done}=await reader.read();if(done)break;buf+=decoder.decode(value,{stream:true});let cut;while((cut=buf.indexOf('\n\n'))>=0){const chunk=buf.slice(0,cut);buf=buf.slice(cut+2);const data=chunk.split('\n').filter(x=>x.startsWith('data:')).map(x=>x.slice(5).trim()).join('\n');if(data)accept(JSON.parse(data))}}}catch(e){if(!stop&&!auth)setError(e.message)}finally{setLive(false);if(!stop)timer=setTimeout(connect,3000)}}connect();return()=>{stop=true;controller.abort();clearTimeout(timer)}},[session]);
 async function act(path,method='POST',body,message='설정을 적용했습니다.'){setBusy(b=>b+1);setError('');if(message===null)setNotice('');try{const result=await api(path,method,body);accept(await api('/state'));if(message!==null){setNotice(message);setTimeout(()=>setNotice(''),4500)}return result}catch(e){setError(e.message);throw e}finally{setBusy(b=>b-1)}}
 const action=(...args)=>act(...args).catch(()=>null);
 const p=state?.plants.find(p=>p.id===selected),plants=state?.plants||[],total=plants.reduce((s,p)=>s+sum(p,'powerKw'),0),rated=plants.reduce((s,p)=>s+sum(p,'ratedKw'),0),gens=plants.flatMap(p=>p.generators||[]);
 const go=id=>{location.hash=id};
 return <div className="app"><aside className="sidebar"><a href="#dashboard" className="brand"><span className="brand-mark"><Zap size={24}/></span><span>GRID<span className="brand-sub">VPP LAB</span></span></a><div className="nav-caption">WORKSPACE</div><nav>{nav.map(([id,label,Icon])=><a key={id} href={'#'+id} className={page===id?'active':''} title={label}><Icon size={20}/><span>{label}</span>{page===id&&<i/>}</a>)}</nav><div className="sidebar-bottom"><div className="lab-icon"><Globe size={21}/></div><strong>Virtual power. Real insight.</strong><p>SCADA · RTU 에뮬레이터</p><span className="version">v{state?.version||'—'} / MQTT v2</span></div></aside><main><header className="topbar"><div className="breadcrumb">워크스페이스 <ChevronRight size={14}/><strong>{nav.find(x=>x[0]===page)?.[1]||'통합 대시보드'}</strong></div><div className="header-actions"><span className={'connection '+(live&&now-updatedAt<=5000?'online':'')}><i/>{updatedAt&&now-updatedAt>5000?`데이터 지연 · ${Math.floor((now-updatedAt)/1000)}초`:!updatedAt?'상태 수신 대기':live?'실시간 연결':'다시 연결 중'}</span><Button kind="primary" onClick={()=>setRegister(true)}><Plus size={16}/> RTU 추가</Button></div></header><div className="content"><div className="page-title"><div><div className="eyebrow">GRID OPERATIONS / {page.toUpperCase()}</div><h1>{nav.find(x=>x[0]===page)?.[1]||'통합 대시보드'}<span className="title-dot"/></h1><p>{({dashboard:'분산 에너지의 흐름을 한눈에. 실시간 발전 상태와 현장 제어를 확인하세요.',devices:'각 RTU의 수집부터 전송, 명령 처리까지 독립적으로 관찰합니다.',lab:'재현 가능한 가상 환경에서 모델과 제어 응답을 검증하세요.',logs:'영속 저장된 운영 이벤트와 장애·제어 기록을 확인하세요.',api:'외부 VPP 시스템을 연결하기 위한 실행 가능한 인터페이스 가이드.'})[page]}</p></div><div className="date-label">VIRTUAL SCADA<br/><span>1초 수집 · MQTT QoS 1</span></div></div>{error&&<div role="alert" className="alert error"><strong>요청을 확인해 주세요</strong><span>{error}</span><button aria-label="오류 닫기" onClick={()=>setError('')}><X size={16}/></button></div>}{notice&&<div role="status" className="alert success"><Check size={17}/>{notice}</div>}{busy>0&&<div className="working" role="status">서버에 적용 중…</div>}
 {!state?<div className="empty">서버 상태를 불러오는 중입니다…</div>:<>{page==='dashboard'&&<><div className="metrics"><Metric label="현재 총 발전량" value={fmt(total/1000,3)} unit="MW" sub="선택 단지에 관계없는 전체 실시간 출력" icon={Zap}/><Metric label="설비 총 정격" value={fmt(rated/1000,2)} unit="MW" sub={`${plants.length}개 단지 · ${gens.length}기 발전기`} icon={Wind}/><Metric label="가동 지시 발전기" value={`${gens.filter(g=>g.on).length} / ${gens.length}`} unit="기" sub={`현재 출력 > 0: ${gens.filter(g=>g.powerKw>0).length}기`} icon={Power}/><Metric label="설비 이용률" value={fmt(rated?total/rated*100:0)} unit="%" sub={`게이트웨이 ${state.gateway?.connected?'연결됨':'연결 확인 필요'}`} icon={Activity}/></div><div className="section-heading"><h2>발전단지 <span>{plants.length}</span></h2><small>단지를 선택하면 아래 관찰 대상이 변경됩니다</small></div><div className="plant-grid">{plants.map(x=><button className={'plant-card '+(x.id===selected?'selected':'')} key={x.id} onClick={()=>setSelected(x.id)}><div className="plant-card-top"><span className="type-icon">{x.type==='solar'?<Sun size={20}/>:<Wind size={20}/>}</span><Badge good={!x.faults?.offline}>{x.faults?.offline?'OFFLINE':typeNames[x.type]}</Badge></div><h3>{x.name}</h3><p>{x.generators.length}기 · 정격 {fmt(sum(x,'ratedKw')/1000,2)} MW</p><div className="plant-power">{fmt(sum(x,'powerKw')/1000,3)} <span>MW</span><ArrowUpRight size={19}/></div><div className="power-track"><i style={{width:Math.min(100,sum(x,'powerKw')/sum(x,'ratedKw')*100)+'%'}}/></div></button>)}</div>{p?<Dashboard key={p.id} p={p} act={action} commands={receiptManager.current} onCommand={sendCommand}/>:<Empty onClick={()=>setRegister(true)}/>}</>}
 {page==='devices'&&<Devices plants={plants} p={p} selected={selected} select={setSelected} gateway={state.gateway} go={go}/>}
 {page==='lab'&&<><PlantSelect plants={plants} selected={selected} select={setSelected}/>{p?<Lab key={p.id} p={p} act={action} busy={busy>0} commands={receiptManager.current} onCommand={sendCommand}/>:<Empty onClick={()=>setRegister(true)}/>}</>}
 {page==='logs'&&<Panel title="운영 이벤트" eyebrow="PERSISTENT AUDIT" action={<Badge>{state.events?.length||0}개 최근 기록</Badge>}><div className="table-wrap"><table><thead><tr><th>시각 · KST (UTC+09:00)</th><th>유형</th><th>메시지</th></tr></thead><tbody>{(state.events||[]).map((e,i)=><tr key={e.id||i} data-event-id={e.id}><td className="mono nowrap"><EventTime event={e}/></td><td><Badge bad={e.level==='error'}>{e.level||e.type}</Badge></td><td>{e.message}</td></tr>)}</tbody></table>{!state.events?.length&&<div className="empty">아직 기록된 이벤트가 없습니다.</div>}</div></Panel>}
 {page==='api'&&<><PlantSelect plants={plants} selected={selected} select={setSelected}/><Guide p={p} gateway={state.gateway} onError={setError}/></>}
 </>}</div><footer><span><ShieldCheck size={14}/> 가상 발전설비 · 실물 안전 인터록 대체 불가</span><span>GRID VPP · SCADA / RTU LAB</span></footer></main>{register&&<Register onClose={()=>setRegister(false)} act={act} onDone={p=>{setSelected(p.id);setRegister(false);go('dashboard')}} onError={setError}/>}{auth&&<div className="modal-backdrop"><form className="modal auth-modal" onSubmit={e=>{e.preventDefault();sessionStorage.setItem('grid-token',authValue);setAuthValue('');setAuth(false);setSession(s=>s+1)}}><div className="eyebrow">SECURE WORKSPACE</div><h2>관리 API 로그인</h2><p>원격 운영 토큰을 입력하세요. 토큰은 이 브라우저 탭의 세션에만 보관됩니다.</p><Field label="API 토큰"><input type="password" autoFocus autoComplete="current-password" required value={authValue} onChange={e=>setAuthValue(e.target.value)}/></Field><Button kind="primary" type="submit">워크스페이스 연결</Button></form></div>}</div>
}
function Empty({onClick}){return <div className="empty"><Wind size={32}/><h3>첫 RTU를 등록해 주세요</h3><p>CSV 또는 TSV를 연결하면 1초 SCADA 데이터 수집이 시작됩니다.</p><Button kind="primary" onClick={onClick}><Plus size={15}/>RTU 추가</Button></div>}
function PlantSelect({plants,selected,select}){return <div className="plant-selector"><Field label="관찰 RTU"><select value={selected} onChange={e=>select(e.target.value)}>{plants.map(p=><option key={p.id} value={p.id}>{p.name} · {typeNames[p.type]}</option>)}</select></Field><span className="mono">{selected||'등록된 RTU 없음'}</span></div>}
function Dashboard({p,act,commands,onCommand}){const [weather,setWeather]=useState({...Object.fromEntries(Object.entries(p.weather||{}).map(([k,v])=>[k,typeof v==='number'?Math.round(v*100)/100:v])),mode:p.mode}),[target,setTarget]=useState(''),[limit,setLimit]=useState(100),[seek,setSeek]=useState(Math.floor(p.seconds||0)),[weatherPending,setWeatherPending]=useState(false),[weatherReceipt,setWeatherReceipt]=useState(null);const weatherAlive=useRef(true),weatherInFlight=useRef(false);useEffect(()=>{weatherAlive.current=true;return()=>{weatherAlive.current=false}},[]);const refreshWeather=async()=>{if(weatherInFlight.current)return;weatherInFlight.current=true;setWeatherPending(true);setWeatherReceipt(null);try{const result=await act('/plants/'+p.id+'/weather/refresh','POST',{},null);if(result&&weatherAlive.current)setWeatherReceipt({target:p.name+' (RTU '+p.id+')',source:result.weatherSource||'확인 필요',error:result.weatherError||null})}finally{weatherInFlight.current=false;if(weatherAlive.current)setWeatherPending(false)}};const d=p.dataset||{},path='/plants/'+p.id;const commandPending=commands.isPending(p.id),command=(action,extra={})=>onCommand(p,{action,...(target?{generatorId:target}:{}),...extra});const last=p.history?.at(-1)||p;return <><div className="dashboard-middle"><Panel title={p.name} eyebrow="LIVE DIGITAL TWIN" className="scene-panel" action={<Badge good>가상 지형 · 개념 모델</Badge>}><div className="scene"><SceneBoundary><Suspense fallback={<div className="scene-fallback">3D 가상 현장을 준비하고 있습니다…</div>}><Scene plant={p}/></Suspense></SceneBoundary><div className="scene-overlay"><span><i/> LIVE MODEL</span><strong>{fmt(sum(p,'powerKw')/1000,3)} <small>MW</small></strong></div><div className="scene-note">드래그 회전 · 스크롤 확대</div></div><div className="scene-footer"><span><Globe size={14}/>{fmt(p.lat,4)}° N / {fmt(p.lon,4)}° E</span><span>{p.coordinateSource||'시뮬레이션 좌표'} · {p.generators.length} generators</span></div></Panel><Panel title="기상 조건" eyebrow="WEATHER INPUT" action={<Wind size={19} className="lime"/>}><form onSubmit={e=>{e.preventDefault();act(path+'/weather','PATCH',weather)}}><Field label="발전 입력 모드"><select value={weather.mode} onChange={e=>setWeather({...weather,mode:e.target.value})}><option value="csv">CSV 원본 출력</option><option value="weather">기상 모델 출력</option></select></Field><div className="form-grid">{[['wind_speed_ms','풍속 (m/s)'],['wind_direction_deg','풍향 (°)'],['irradiance_wm2','일사 (W/m²)'],['temperature','온도 (°C)']].map(([k,l])=><Num key={k} label={l} value={weather[k]} onChange={v=>setWeather({...weather,[k]:v})}/>)}</div><div className="button-row"><Button kind="primary" type="submit">기상 적용</Button><Button type="button" disabled={weatherPending} onClick={refreshWeather}><RefreshCw size={14}/>{weatherPending?'KMA 조회 중…':'KMA 조회'}</Button></div></form>{weatherReceipt&&<p role={weatherReceipt.error?'alert':'status'} className={weatherReceipt.error?'hint warning':'hint'}>{weatherReceipt.target} · {weatherReceipt.error?'기상 조회 오류: '+weatherReceipt.error:'조회 요청 처리가 완료되었습니다. 새 관측 적용 여부는 실제 출처와 관측 시각을 확인하세요.'} · 반환 출처: {weatherReceipt.source}</p>}<div className="weather-info"><span>관측소 <b>{p.station}</b> · 출처 <b>{p.weatherSource||'—'}</b></span><span>관측 시각 {time(p.weatherObservedAt)}</span><span>현재 {fmt(p.weather?.wind_speed_ms)} m/s · {fmt(p.weather?.irradiance_wm2)} W/m²</span>{p.weatherError&&<span className="warning">{p.weatherError}</span>}</div></Panel></div><div className="dashboard-bottom"><Panel title="발전 출력 추이" eyebrow="LAST 180 SAMPLES" action={<div className="legend"><span><i/>실제 출력</span><span><i/>가용 출력</span></div>}><Chart history={p.history||[]} /><div className="chart-meta"><span>원본 시각 <b>{time(last.sourceTimestamp||p.sourceTimestamp)}</b></span><span>{fmt(d.rowCount??d.rows,0)}행 · {d.interpolation||'linear'} · 반복 {p.loopCount??Math.floor((p.simulationSeconds||0)/(d.durationSeconds||1))}회</span></div><div className="seek"><label htmlFor="seek">CSV 위치 {fmt(seek,0)}초</label><input id="seek" type="range" min="0" max={Math.max(0,(d.durationSeconds||d.duration||600)-1)} step="1" value={seek} onChange={e=>setSeek(Number(e.target.value))}/><Button onClick={()=>act(path+'/replay','POST',{seconds:seek},'원본 재생 위치를 이동했습니다.')}>이동</Button></div></Panel><Panel title="발전 출력 제어" eyebrow="REST → RTU → SCADA"><Field label="제어 대상"><select value={target} onChange={e=>setTarget(e.target.value)}><option value="">단지 전체</option>{p.generators.map(g=><option key={g.id}>{g.id}</option>)}</select></Field><label className="slider-label" htmlFor="limit">정격 대비 출력 상한 <b>{limit}%</b></label><input id="limit" type="range" min="0" max="100" value={limit} onChange={e=>setLimit(Number(e.target.value))}/><div className="range-label"><span>0%</span><span>100%</span></div><Button disabled={commandPending} kind="primary full" onClick={()=>command('set_limit',{limitPct:limit})}>출력 상한 적용</Button><div className="button-row"><Button disabled={commandPending} onClick={()=>command('start')}><Play size={14}/>기동</Button><Button disabled={commandPending} kind="danger" onClick={()=>command('stop')}><Power size={14}/>정지</Button></div><p className="hint">{commandPending?'명령 전송 응답 대기 중 · 최대 15초':'제한·기동·정지는 램프와 가용 출력에 따라 적용됩니다.'}</p></Panel></div><CommandReceipts p={p} commands={commands}/><Panel title="발전기 상태" eyebrow="GENERATOR TELEMETRY" action={<Badge>{p.generators.length} UNITS</Badge>}><div className="table-wrap"><table><thead><tr><th>발전기</th><th>상태</th><th>현재 / 정격 (kW)</th><th>상한</th><th>단지 전압 원본 (V)</th><th>단지 원본 전류 (A)</th><th>단지 추정 전류 (A)</th><th>제어</th></tr></thead><tbody>{p.generators.map(g=><tr key={g.id}><td><span className="generator-id">{g.type==='solar'?<Sun size={15}/>:<Wind size={15}/>} {g.id}</span></td><td><Badge good={g.on}>{g.state||g.status||(g.on?'ON':'OFF')}</Badge></td><td className="mono">{fmt(g.powerKw)} <span className="muted">/ {fmt(g.ratedKw,0)}</span></td><td>{fmt(g.limitPct,0)}%</td><td>{fmt(p.electrical?.voltage)}</td><td>{fmt(p.electrical?.sourceCurrentA)}</td><td>{fmt(p.electrical?.estimatedCurrentA)}</td><td><Button disabled={commandPending} onClick={()=>onCommand(p,{action:g.on?'stop':'start',generatorId:g.id})}>{g.on?'정지':'기동'}</Button></td></tr>)}</tbody></table></div></Panel></>}
function Chart({history}){const rows=history.slice(-180),w=900,h=190,max=Math.max(1,...rows.map(r=>Math.max(r.powerKw??r.totalPowerKw??0,r.availableKw??r.totalAvailableKw??0)));const points=key=>rows.map((r,i)=>`${i/(Math.max(rows.length-1,1))*w},${h-(Number(r[key]??r[key==='powerKw'?'totalPowerKw':'totalAvailableKw'])||0)/max*(h-20)}`).join(' ');return <div className="chart"><div className="chart-unit">kW · {fmt(max,0)}</div>{rows.length?<svg viewBox={`0 0 ${w} ${h+10}`} role="img" aria-label="최근 180개 실제 및 가용 출력"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#c5f16c" stopOpacity=".18"/><stop offset="100%" stopColor="#c5f16c" stopOpacity="0"/></linearGradient></defs>{[0,1,2,3].map(i=><line key={i} x1="0" y1={i*h/3} x2={w} y2={i*h/3} stroke="#243b31" strokeDasharray="4 6"/>)}<polygon points={`0,${h} ${points('powerKw')} ${w},${h}`} fill="url(#fill)"/><polyline points={points('availableKw')} fill="none" stroke="#6b9f88" strokeWidth="2" strokeDasharray="6 5"/><polyline points={points('powerKw')} fill="none" stroke="#c5f16c" strokeWidth="2.5"/></svg>:<div className="empty">수집한 출력 데이터가 아직 없습니다.</div>}<div className="chart-axis"><span>{rows[0]?time(rows[0].timestamp):'—'}</span><span>{rows.length} / 180 points</span><span>현재</span></div></div>}
function Devices({plants,p,selected,select,gateway,go}){const [search,setSearch]=useState('');const m=p?.metrics||{},q=m.queue||m.outbox||{};return <><div className="metrics"><Metric label="등록 / 정상 RTU" value={`${plants.length} / ${plants.filter(x=>x.metrics?.health==='HEALTHY').length}`} sub="단말별 독립 MQTT 연결" icon={Radio}/><Metric label="수집 샘플" value={fmt(plants.reduce((s,p)=>s+(p.metrics?.generatedSamples||0),0),0)} unit="개" sub="RTU 로컬 영속 수집"/><Metric label="PUBACK 완료" value={fmt(plants.reduce((s,p)=>s+(p.metrics?.telemetryConfirmed||p.metrics?.telemetryConfirmed||0),0),0)} unit="건" sub="브로커 접수 · VPP 업무 처리와 다름"/><Metric label="게이트웨이" value={gateway?.connected?'CONNECTED':'OFFLINE'} sub={gateway?.clientId||'관리 MQTT 연결'}/></div><div className="run-strip"><span>명령 수신 {fmt(plants.reduce((n,x)=>n+(x.metrics?.commandsReceived||0),0),0)}건</span><span>접수 {fmt(plants.reduce((n,x)=>n+(x.metrics?.commandsAccepted||0),0),0)}건</span><span>거절 {fmt(plants.reduce((n,x)=>n+(x.metrics?.commandsRejected||0),0),0)}건</span><span>공용 프로세스 RSS {fmt((gateway?.rssBytes||0)/1048576)} MiB · 가동 {fmt(gateway?.uptimeSeconds,0)}초</span></div><Panel title="디바이스 목록" eyebrow="INDEPENDENT RTU CONNECTIONS" action={<input aria-label="RTU 이름 또는 ID 검색" placeholder="이름 또는 ID 검색" value={search} onChange={e=>setSearch(e.target.value)}/>}><div className="table-wrap"><table><thead><tr><th>단말</th><th>연결 상태</th><th>최근 수집</th><th>대기 메시지</th><th>상세</th></tr></thead><tbody>{plants.filter(p=>(p.name+' '+p.id).toLowerCase().includes(search.toLowerCase())).map(p=><tr key={p.id} className={p.id===selected?'row-selected':''}><td><b>{p.name}</b><small className="block mono">{p.id}</small></td><td><Badge good={p.metrics?.connected} bad={p.faults?.offline}>{p.metrics?.health|| (p.metrics?.connected?'연결':'단절')}</Badge></td><td>{time(p.metrics?.lastSampleAt)}</td><td>{fmt(p.metrics?.pendingMessages??p.metrics?.queue?.pending,0)}</td><td><Button onClick={()=>select(p.id)}>선택 <ChevronRight size={13}/></Button></td></tr>)}</tbody></table></div></Panel>{p&&<><div className="section-heading"><h2>{p.name} <span>RTU 상세</span></h2><Button onClick={()=>go('dashboard')}>발전 제어 화면 <ArrowUpRight size={15}/></Button></div><div className="two-cols"><Panel title="연결 · 전송" eyebrow="TRANSPORT"><Details obj={{'Client ID':m.clientId,'연결':m.connected?'연결됨':'연결 안 됨','상태':m.health,'발행 시도':m.telemetryAttempts,'발행 완료':m.telemetryConfirmed??m.telemetryConfirmed,'실패':m.telemetryFailed,'전송 바이트':m.confirmedBytes??m.confirmedBytes,'최근 PUBACK':time(m.lastConfirmedAt),'오류':m.lastError||'없음'}}/></Panel><Panel title="수집 · 디스크 큐" eyebrow="STORE & FORWARD"><Details obj={{'누적 수집':m.generatedSamples,'최근 수집':time(m.lastSampleAt),'대기 메시지':m.pendingMessages??q.pending,'미배치 샘플':m.unbatchedSamples??q.unbatched,'CSV 행':p.dataset?.rowCount,'보간':p.dataset?.interpolation,'단위 / 의미':`${p.dataset?.unit} / ${p.dataset?.semantics}`,'원본 전압 (V)':p.electrical?.voltage,'원본 전류 (A)':p.electrical?.sourceCurrentA,'제어 후 추정 전류 (A)':p.electrical?.estimatedCurrentA}}/></Panel></div><Panel title="실제 단말 토픽" eyebrow="MQTT"><Code text={m.telemetryTopic||`${gateway?.prefix||'vpp'}/rtu/${p.id}/telemetry`}/><p className="hint">QoS 1 PUBACK는 브로커 접수입니다. 외부 VPP의 업무 처리를 보장하지 않습니다.</p></Panel><Commands key={p.id} p={p}/></>}</>}
function Details({obj}){return <dl className="details">{Object.entries(obj).map(([k,v])=><React.Fragment key={k}><dt>{k}</dt><dd>{v==null?'—':typeof v==='number'?fmt(v,2):String(v)}</dd></React.Fragment>)}</dl>}
function Lab({p,act,busy,commands,onCommand}){const [tab,setTab]=useState(0);return <><div className="run-strip"><Badge good={!p.faults?.offline}>{p.faults?.offline?'OFFLINE':'ONLINE'}</Badge><span className="mono">run {p.runId}</span><span>{fmt(p.simulationSeconds,0)} 가상 초</span></div><div className="tabs">{['재생·장애 시험','발전기·기상 모델','목표값·처리 결과','저장 시나리오'].map((t,i)=><button key={t} onClick={()=>setTab(i)} className={tab===i?'active':''}>{t}</button>)}</div>{tab===0&&<Replay p={p} act={act}/>} {tab===1&&<Model p={p} act={act}/>} {tab===2&&<Target p={p} commands={commands} onCommand={onCommand}/>} {tab===3&&<Scenarios key={p.id} p={p} act={act} busy={busy}/>}</>}
function Replay({p,act}){const [replay,setReplay]=useState(p.replay),[faults,setFaults]=useState(p.faults);const path='/plants/'+p.id;return <div className="two-cols"><Panel title="재생 엔진" eyebrow="DETERMINISTIC SIMULATION"><Field label="재생 배속"><select value={replay.speed} onChange={e=>setReplay({...replay,speed:Number(e.target.value)})}>{[1,2,5,10,30,60].map(x=><option key={x} value={x}>{x}×</option>)}</select></Field><div className="form-grid"><Num label="난수 시드" value={replay.seed} onChange={seed=>setReplay({...replay,seed})}/><Num label="출력 변동률 (%)" min="0" max="50" value={replay.noisePct} onChange={noisePct=>setReplay({...replay,noisePct})}/></div><label className="check"><input type="checkbox" checked={replay.freezeLiveWeather||false} onChange={e=>setReplay({...replay,freezeLiveWeather:e.target.checked})}/>라이브 기상 자동 갱신 중지</label><div className="button-row"><Button kind="primary" onClick={()=>act(path+'/replay','POST',replay)}>재생 설정 적용</Button><Button onClick={()=>{const next=!p.replay.paused;setReplay({...replay,paused:next});act(path+'/replay','POST',{paused:next})}}>{p.replay.paused?<Play size={15}/>:<Pause size={15}/>} {p.replay.paused?'재생':'일시정지'}</Button></div><p className="hint">배속은 모델 가상 시간에 적용됩니다. 명령 유효기간과 timeout은 실제 시간을 사용합니다.</p><Details obj={{'현재 배속':`${p.replay.speed}×`,'재생 상태':p.replay.paused?'일시정지':'재생 중','디스크 대기':p.metrics?.pendingMessages,'미배치 샘플':p.metrics?.unbatchedSamples}}/></Panel><Panel title="RTU 장애 주입" eyebrow="FAULT INJECTION" action={<Badge bad={Object.values(p.faults||{}).some(Boolean)}>선택 RTU에만 적용</Badge>}>{[['offline','MQTT 연결 단절'],['sensorFreeze','센서 수집 중지'],['scadaReject','SCADA 전달 거절'],['actuatorStuck','실제 발전 출력 고정']].map(([k,l])=><label className="check" key={k}><input type="checkbox" checked={faults[k]||false} onChange={e=>setFaults({...faults,[k]:e.target.checked})}/>{l}</label>)}<div className="form-grid"><Num label="지연 (ms)" min="0" max="30000" value={faults.latencyMs} onChange={latencyMs=>setFaults({...faults,latencyMs})}/><Num label="발행 시도 실패율 (%)" min="0" max="100" value={faults.dropPct} onChange={dropPct=>setFaults({...faults,dropPct})}/></div><div className="button-row"><Button kind="danger" onClick={()=>act(path+'/faults','PATCH',faults)}>장애 적용</Button><Button onClick={()=>{const clean={offline:false,sensorFreeze:false,scadaReject:false,actuatorStuck:false,latencyMs:0,dropPct:0};setFaults(clean);act(path+'/faults','PATCH',clean,'모든 장애를 해제했습니다.')}}>모든 장애 해제</Button></div><p className="hint">센서 수집이 중지된 구간은 복구 후 실제 계측값처럼 채워지지 않습니다. 연결 단절 동안에도 정상 센서는 로컬 저장을 계속합니다.</p></Panel></div>}
function Model({p,act}){const [id,setId]=useState(p.generators[0]?.id),[edit,setEdit]=useState({...p.generators[0]}),[curve,setCurve]=useState(JSON.stringify(p.generators[0]?.windCurve??null)),[station,setStation]=useState(p.station),[csv,setCSV]=useState(''),[err,setErr]=useState('');const path='/plants/'+p.id;function choose(id){const g=p.generators.find(g=>g.id===id);setId(id);setEdit({...g});setCurve(JSON.stringify(g.windCurve??null))}return <div className="two-cols"><Panel title="발전기 동특성" eyebrow="GENERATOR MODEL"><Field label="발전기 선택"><select value={id} onChange={e=>choose(e.target.value)}>{p.generators.map(g=><option key={g.id}>{g.id}</option>)}</select></Field><form onSubmit={e=>{e.preventDefault();try{const keys=['ratedKw','rampKwPerSec','startupDelaySeconds',...(edit.type==='wind'?['cutInMs','ratedWindMs','cutOutMs']:['solarEfficiency','temperatureCoefficient'])];const data=Object.fromEntries(keys.map(k=>[k,edit[k]]).filter(([,v])=>v!==undefined));if(edit.type==='wind')data.windCurve=JSON.parse(curve);setErr('');act(path+'/generators/'+id,'PATCH',data)}catch{setErr('풍력 곡선은 [[풍속, 비율], …] JSON 또는 null이어야 합니다.')}}}><div className="form-grid">{[['ratedKw','정격 (kW)'],['rampKwPerSec','램프 (kW/s)'],['startupDelaySeconds','기동 지연 (초)'],...(edit.type==='wind'?[['cutInMs','Cut-in (m/s)'],['ratedWindMs','정격 풍속 (m/s)'],['cutOutMs','Cut-out (m/s)']]:[['solarEfficiency','태양광 보정계수'],['temperatureCoefficient','온도 계수 (1/°C)']])].map(([k,l])=><Num key={k} label={l} value={edit[k]??(k==='startupDelaySeconds'?0:'')} onChange={v=>setEdit({...edit,[k]:v})}/>)}</div>{edit.type==='wind'&&<Field label="사용자 풍력 곡선 (JSON)" hint="예: [[3,0],[8,0.4],[12,1]] · null은 기본 3차 곡선"><textarea value={curve} onChange={e=>setCurve(e.target.value)} rows="3"/></Field>}{err&&<p role="alert" className="warning">{err}</p>}<Button kind="primary" type="submit">모델 저장</Button></form><p className="hint">모델 변경 시 해당 단지의 진행 중 명령 추적은 cancelled로 종료됩니다. 이미 적용한 제어 상태는 자동 복원되지 않습니다.</p></Panel><Panel title="관측소 · 일사 입력" eyebrow="WEATHER MODEL"><Num label="KMA 관측소 번호" min="1" max="9999" value={station} onChange={setStation}/><Button onClick={()=>act(path+'/station','PATCH',{station})}>관측소 적용</Button><div className="divider"/><Field label="별도 일사 CSV/TSV"><input type="file" accept=".csv,.tsv,text/csv,text/tab-separated-values" onChange={async e=>{if(e.target.files[0])setCSV(await e.target.files[0].text())}}/></Field><Field label="일사 데이터" hint="timestamp,irradiance_wm2 · 원본 SCADA 시간에 정렬"><textarea rows="6" value={csv} onChange={e=>setCSV(e.target.value)} placeholder={'timestamp,irradiance_wm2\n2026-01-01T00:00:00Z,300'}/></Field><div className="button-row"><Button kind="primary" disabled={!csv.trim()} onClick={()=>act(path+'/irradiance','POST',{csv})}>일사 등록</Button><Button onClick={()=>{setCSV('');act(path+'/irradiance','POST',{csv:null})}}>일사 해제</Button></div><p className="hint">범위 밖에서는 기존 CSV·수동 일사로 돌아갑니다. KMA 누적 SI를 순간 W/m²로 변환하지 않습니다.</p><Details obj={{'일사 출처':p.irradianceSource,'등록 행':p.irradianceDataset?.rowCount}}/></Panel></div>}
function Target({p,commands,onCommand}){const [form,setForm]=useState({generatorId:'',targetKw:0,toleranceKw:1,timeoutSeconds:120,validSeconds:30,priority:50}),[inputError,setInputError]=useState(null);const formRef=useRef(null);return <><Panel title="목표 출력 시험" eyebrow="REST TEST · EXTERNAL VPP USES MQTT"><form ref={formRef} noValidate onSubmit={e=>{e.preventDefault();if(commands.isPending(p.id))return;const checked=validateCommandForm(form,Date.now());if(checked.error){setInputError(checked.error);formRef.current.elements.namedItem(checked.error.field)?.focus();return}setInputError(null);const {validSeconds,generatorId,...rest}=form;onCommand(p,{...rest,...(generatorId?{generatorId}:{}),action:'set_target',expiresAt:checked.expiresAt})}}><div className="form-grid three"><Field label="제어 대상"><select value={form.generatorId} onChange={e=>{setForm({...form,generatorId:e.target.value});setInputError(null)}}><option value="">단지 전체 · 정격 비례 배분</option>{p.generators.map(g=><option key={g.id}>{g.id}</option>)}</select></Field>{commandFields.map(({key,label,min,max,hint})=>{const id='command-'+p.id+'-'+key,invalid=inputError?.field===key;return <Field key={key} label={label}><input id={id} name={key} type="number" step="any" required min={min} max={max} value={form[key]} aria-invalid={invalid||undefined} aria-describedby={id+'-hint'+(invalid?' '+id+'-error':'')} onChange={e=>{setForm({...form,[key]:e.target.value===''?'':Number(e.target.value)});setInputError(null)}}/><small id={id+'-hint'}>{hint}</small>{invalid&&<small id={id+'-error'} role="alert" className="warning">{inputError.message}</small>}</Field>})}</div><Button disabled={commands.isPending(p.id)} kind="primary" type="submit"><ArrowUpRight size={16}/>{commands.isPending(p.id)?'명령 전송 응답 대기 중…':'목표값 전송'}</Button></form><div className="flow"><span>REST 시험</span><ChevronRight/><span>RTU 검증·저장</span><ChevronRight/><span>SCADA 전달</span><ChevronRight/><span>센서 피드백</span></div><p className="hint">목표값은 기동을 포함합니다. 실제 가용 출력이 부족하면 timed_out이 될 수 있습니다. 0 kW 목표는 정지 명령과 다릅니다. 유효한 만료일도 서버 시각과 전달 지연에 따라 만료될 수 있습니다.</p></Panel><CommandReceipts p={p} commands={commands}/><Commands key={p.id} p={p}/></>}

const receiptLabels={accepted:'접수됨 · 실행 결과 확인 필요',executing:'SCADA 전달됨 · 피드백 확인 필요',completed:'실제 피드백 완료',rejected:'거절됨',expired:'만료됨',failed:'실패',timed_out:'시간 초과',superseded:'다른 명령으로 대체됨',cancelled:'취소됨'};
function CommandReceipts({p,commands}){const rows=commands.list(p.id),olderUnknown=rows.slice(1).filter(r=>!r.confirmed&&!r.pending).length;const item=r=><article className="command-receipt" key={r.commandId} data-command-id={r.commandId} data-rtu-id={r.plantId}><div className="receipt-heading"><strong>{r.action} · {r.generatorId||'단지 전체'}</strong><Badge good={r.status==='completed'} bad={r.confirmed&&!['accepted','executing','completed'].includes(r.status)}>{r.pending?'응답 대기':r.confirmed?r.status:'미확정'}</Badge></div><p role="status">{r.pending?'POST 응답 대기 중 · 최대 15초':r.confirmed?receiptLabels[r.status]:'접수 여부 확인 필요 · 자동 재전송하지 않습니다.'}</p><small className="block">{r.plantName} · REST · {time(r.sentAt)}</small><small className="block mono">RTU {r.plantId}<br/>명령 {r.commandId}</small>{r.reason&&<p className="receipt-reason">{r.reason}</p>}{r.problem&&<p className="warning">{r.problem}</p>}{r.refreshWarning&&<p className="warning">{r.refreshWarning}</p>}{r.checkWarning&&<p className="warning">{r.checkWarning}</p>}<Button disabled={r.pending||r.checking} onClick={()=>commands.recheck(r.plantId,r.commandId)}>{r.checking?'저장 상태 확인 중…':'저장 상태 확인'}</Button></article>;return <section className="panel receipt-panel" aria-label="이 탭의 명령 전송 확인" data-rtu-id={p.id}><div className="panel-head"><h2>이 탭의 명령 전송 확인</h2><small>{p.name}</small></div>{olderUnknown>0&&<p className="warning" role="status">이전 미확정 명령 {olderUnknown}건이 남아 있습니다. 아래 이전 확인을 펼쳐 확인하세요.</p>}{rows.length?item(rows[0]):<p className="hint">이 탭에서 보낸 명령이 없습니다.</p>}{rows.length>1&&<details className="receipt-history"><summary>이전 확인 {rows.length-1}건</summary>{rows.slice(1).map(item)}</details>}<p className="hint">RTU별 이 탭 메모리 최근 20개만 표시합니다. 초과한 오래된 항목과 새로고침 후 기록은 보존되지 않습니다. 저장 상태 확인은 최근 200개 서버 목록을 읽으며, 미발견이 미접수를 뜻하지 않습니다.</p></section>}
function Commands({p}){const [rows,setRows]=useState([]),[error,setError]=useState(''),[exporting,setExporting]=useState(false),[exportError,setExportError]=useState('');const exportingRef=useRef(false);const exportCommands=async()=>{if(exportingRef.current)return;exportingRef.current=true;setExporting(true);setExportError('');try{const id=p.id.replace(/[^a-zA-Z0-9-]/g,'').slice(0,80);await download('/plants/'+p.id+'/commands/export',`command-states-${id}-${new Date().toISOString().replace(/[^0-9]/g,'')}.json`)}catch(e){setExportError(e.message)}finally{exportingRef.current=false;setExporting(false)}};useEffect(()=>{setRows([]);setError('');setExportError('');let active=true;const load=()=>api('/plants/'+p.id+'/commands').then(r=>{if(active){setRows(r.slice(0,20));setError('')}}).catch(e=>active&&setError(e.message));load();const t=setInterval(load,2000);return()=>{active=false;clearInterval(t)}},[p.id]);return <Panel title="명령 처리 결과" eyebrow="RECENT 20 COMMANDS" action={<Button disabled={exporting} onClick={exportCommands}><Download size={14}/>{exporting?'내보내는 중…':'최근 명령 상태 JSON 내보내기'}</Button>}><p className="hint">선택 RTU: {p.name} · 최근 갱신 순 최대 20개 저장 상태 스냅샷입니다. 외부 VPP 수신 증거나 전체 감사 로그가 아닙니다. 상세 원인은 화면에서 확인하세요.</p>{exportError&&<div role="alert" className="alert error">{exportError}</div>}<div className="table-wrap"><table><thead><tr><th>명령 / 출처</th><th>수명주기</th><th>목표 / 실제 (kW)</th><th>SCADA 전달시각</th><th>원인</th></tr></thead><tbody>{rows.map(c=><tr key={c.commandId}><td><b>{c.action}</b> <small>{c.source}</small><small className="block mono">{c.commandId}</small></td><td><Badge good={c.status==='completed'} bad={['failed','rejected','timed_out','expired'].includes(c.status)}>{c.status}</Badge></td><td>{fmt(c.targetKw??c.request?.targetKw??(c.targets?.length&&c.targets.every(t=>Number.isFinite(t.targetKw))?c.targets.reduce((n,t)=>n+t.targetKw,0):null))} / {fmt(c.actualKw)}</td><td>{time(c.dispatchedAt)}</td><td>{c.reason||'—'}</td></tr>)}</tbody></table>{!rows.length&&<div className="empty">{error||'아직 접수된 명령이 없습니다.'}</div>}</div></Panel>}
function Scenarios({p,act,busy}){
 const [name,setName]=useState(''),[rows,setRows]=useState([]),[error,setError]=useState(''),[loading,setLoading]=useState(true),[pending,setPending]=useState(false);
 const mounted=useRef(false),generation=useRef(0),inFlight=useRef(false);
 const load=async()=>{const revision=++generation.current;setLoading(true);setError('');try{const result=await api('/scenarios');if(mounted.current&&revision===generation.current)setRows(result)}catch(e){if(mounted.current&&revision===generation.current)setError(e.message)}finally{if(mounted.current&&revision===generation.current)setLoading(false)}};
 useEffect(()=>{mounted.current=true;load();return()=>{mounted.current=false;generation.current++}},[p.id]);
 const perform=async(task,after)=>{if(inFlight.current||busy)return;inFlight.current=true;setPending(true);setError('');try{const result=await task();if(result&&mounted.current)await after?.()}catch(e){if(mounted.current)setError(e.message)}finally{inFlight.current=false;if(mounted.current)setPending(false)}};
 const targetLabel=`${p.name} (RTU ${p.id})`,visible=rows.filter(s=>s.plantId===p.id),blocked=busy||pending;
 return <Panel title={`${p.name} · 저장된 시나리오`} eyebrow="SELECTED RTU / REPRODUCIBLE SNAPSHOTS"><form className="inline-form" onSubmit={e=>{e.preventDefault();perform(()=>act('/scenarios','POST',{name,plantId:p.id},`${targetLabel}의 시나리오를 저장했습니다.`),async()=>{setName('');await load()})}}><Field label="시나리오 이름"><input value={name} onChange={e=>setName(e.target.value)} maxLength="80" required disabled={blocked} placeholder="예: 강풍·50% 제한 시험"/></Field><Button kind="primary" type="submit" disabled={blocked}>현재 상태 저장</Button></form><p className="hint">선택 RTU {p.name}의 시나리오만 표시합니다. 다른 단지의 시나리오는 위 RTU 선택에서 변경하세요.</p><p className="hint">복원은 표시된 RTU에 새로운 runId를 생성하고 활성 명령을 취소합니다. 라이브 기상을 동결하고 저장된 일시정지 상태를 유지합니다. 기존 outbox는 삭제하지 않습니다.</p>{pending&&<p role="status" className="hint">{p.name}의 시나리오 요청을 처리하고 있습니다.</p>}{error&&<p role="alert" className="warning">{error}</p>}<div className="scenario-list">{visible.map(s=><div className="scenario" key={s.id}><div><h3>{s.name}</h3><small>{time(s.createdAt)} · {p.name} · {s.plantId}</small></div><div className="button-row"><Button disabled={blocked} onClick={()=>perform(()=>act('/scenarios/'+s.id+'/run','POST',{},`${targetLabel}에 시나리오 “${s.name}”를 복원했습니다.`))}>복원·재실행</Button><Button disabled={blocked} onClick={()=>perform(async()=>{await download('/scenarios/'+s.id+'/export',s.name+'.json');return true})}><Download size={15}/>JSON</Button></div></div>)}</div>{loading&&<div role="status" className="empty">{p.name}의 저장 시나리오를 불러오는 중입니다.</div>}{!loading&&!error&&!visible.length&&<div className="empty">{p.name}에 저장된 시나리오가 없습니다. 다른 단지는 위 RTU 선택에서 변경하세요.</div>}</Panel>
}
function Code({text}){const [copied,setCopied]=useState(false);return <div className="code"><button aria-label="코드 복사" onClick={()=>navigator.clipboard.writeText(text).then(()=>{setCopied(true);setTimeout(()=>setCopied(false),1800)}).catch(()=>setCopied(false))}>{copied?<Check size={16}/>:<Copy size={16}/>}</button><pre>{text}</pre></div>}
function Guide({p,gateway,onError}){const [tab,setTab]=useState(0),id=p?.id||'YOUR_RTU_UUID',prefix=gateway?.prefix||'vpp',base=p?.metrics?.telemetryTopic?.replace(/\/telemetry$/,'')||`${prefix}/rtu/${id}`;const command=JSON.stringify({schemaVersion:2,commandId:'새 UUID를 사용하세요',action:'set_target',targetKw:100,toleranceKw:1,timeoutSeconds:120,expiresAt:new Date(Date.now()+30000).toISOString(),priority:50},null,2);return <><div className="tabs">{['연결 준비','SCADA 데이터','목표값·결과','시험 절차','운영 설정'].map((s,i)=><button key={s} className={tab===i?'active':''} onClick={()=>setTab(i)}>{s}</button>)}</div><Panel title={['외부 VPP 연결 준비','전체 SCADA 데이터','목표값과 결과 수명주기','최초 연동 시험','운영·보안 설정'][tab]} eyebrow="INTEGRATION GUIDE / MQTT SCHEMA V2" action={<Button onClick={()=>download('/guide','GRID-VPP-integration.md').catch(e=>onError(e.message))}><Download size={15}/>전체 규격 Markdown</Button>}><div className="guide">{tab===0&&<><h3>하나의 RTU, 하나의 발전단지</h3><p>SCADA 전체 데이터는 RTU → MQTT → 외부 VPP로 전달됩니다. 외부 VPP의 목표값은 MQTT → RTU 검증·변환 → SCADA 제어 → 센서 피드백을 거쳐 결과로 돌아옵니다.</p><div className="flow"><span>가상 SCADA</span><ChevronRight/><span>독립 RTU</span><ChevronRight/><span>MQTT</span><ChevronRight/><span>외부 VPP</span></div><h3>선택 RTU 구독 토픽</h3><Code text={`${base}/telemetry\n${base}/status\n${base}/ack\n${base}/command-status`}/><p>원격 PC의 localhost는 해당 PC 자신입니다. 배포 브로커의 실제 주소와 TLS 인증 정보를 설정하세요. RTU와 VPP는 서로 다른 clientId를 사용해야 합니다.</p><p>telemetry·명령·결과는 QoS 1을 사용합니다. 명령 retain은 반드시 false입니다. status retained/LWT는 단말 연결 상태를 표현합니다.</p></>}{tab===1&&<><h3>10분 원본 → 1초 SCADA → 기본 60초 배치</h3><p>telemetry는 배치 samples에 전체 SCADA 프레임을 보냅니다. 각 프레임에는 발전기별 실제·가용·목표 출력, 기상, 전기값, 재생 및 장애 상태가 포함됩니다.</p><Code text={JSON.stringify({schemaVersion:2,rtuId:id,messageId:'immutable-uuid',sequence:1,runId:'scenario-run-uuid',samples:[{timestamp:'현재 수집 UTC 시각',sourceTimestamp:'CSV 원본 UTC 시각',simulationSeconds:1,powerKw:100,availableKw:120,generators:[]} ]},null,2)}/><p>timestamp는 수집시각, sourceTimestamp는 원본 재생시각, simulationSeconds는 가상 시간입니다. messageId와 sequence는 재전송 시 불변입니다. sequence는 명령 결과와도 공유하므로 telemetry 번호의 간격만으로 유실을 판단하지 마세요.</p><p>null은 측정이 없음을 의미합니다. 전압·원본 전류와 제어 후 추정 전류를 구별하세요. 좌표·3D·발전 모델은 가상이며 실제 현장 계측이나 제조사 인증 모델이 아닙니다.</p><p>SQLite outbox는 PUBACK 이후 전송 완료로 표시되고 보존 기간에 따라 정리됩니다. 브로커 PUBACK는 외부 VPP의 업무 처리 완료가 아닙니다. VPP는 messageId로 중복 제거해야 합니다.</p></>}{tab===2&&<><h3>목표값 발행 · retain=false</h3><Code text={`${base}/setpoint\n\n${command}`}/><h3>제어 및 결과 토픽</h3><Code text={`${base}/command\n${base}/command-status`}/><p>set_target은 정격 비례 목표 kW 배분과 기동을 수행합니다. generatorId를 지정하면 한 기에만 적용됩니다. set_limit은 % 상한, start는 기동, stop은 램프 정지를 수행합니다.</p><div className="flow"><span>accepted</span><ChevronRight/><span>executing</span><ChevronRight/><span>completed</span></div><p>accepted는 영속 접수, executing은 SCADA 전달, completed는 허용 오차 안의 센서 피드백입니다. rejected·expired·failed·timed_out·superseded·cancelled는 종료 사유를 구분합니다.</p><p>동일 commandId와 동일 원문은 재실행하지 않습니다. 같은 ID에 다른 본문 또는 RTU는 거절됩니다. 유효기간도 본문의 일부입니다. 더 높은 우선순위의 활성 명령과 충돌하는 새 명령은 거절됩니다.</p><p>timeout·취소는 추적만 종료하며 이미 적용된 제어값을 복원하지 않습니다. 정지가 필요하면 stop을 명시하세요.</p></>}{tab===3&&<><h3>1. 수집과 상태를 관찰합니다</h3><Code text={`RTU_ID=${id} npm run vpp:monitor`}/><h3>2. 가용 출력을 확인하고 목표를 전달합니다</h3><Code text={`RTU_ID=${id} TARGET_KW=100 npm run vpp:dispatch\nRTU_ID=${id} TARGET_KW=100 VPP_REPORT_FILE=/absolute/result.json VPP_CONNECT_TIMEOUT_MS=10000 npm run vpp:dispatch`}/><p>UI의 목표값 시험은 REST 경로입니다. 외부 VPP 연동 확인에는 별도 MQTT 클라이언트를 사용하세요. completed의 actualKw/errorKw와 SCADA 전달시각을 확인합니다.</p><h3>3. 장애와 복원을 검증합니다</h3><p>시험 전용 RTU에서 offline을 적용해 로컬 수집·outbox 증가를 확인한 뒤 해제하고 재전송을 관찰합니다. offline은 해당 RTU 연결만 중단합니다. 센서 수집 중지와 출력 고정도 구분해 시험하고 종료 후 모든 장애를 해제하세요.</p><p>시나리오 복원은 모델 입력과 상태를 재현합니다. MQTT 지연과 외부 처리시간의 동일성을 보장하지 않습니다.</p></>}{tab===4&&<><h3>인증 및 TLS</h3><p>관리 API는 Authorization: Bearer 토큰으로 보호합니다. 토큰은 URL·로그·이미지에 넣지 마세요. MQTT 인증과 관리 API 인증은 별도입니다. 브로커 자격증명, TLS CA·인증서·개인키는 서버 환경/Secret에 저장합니다.</p><Code text={'MQTT_URL=mqtts://YOUR_BROKER:8883\nMQTT_PREFIX=vpp\nMQTT_USERNAME=YOUR_USERNAME\nMQTT_PASSWORD=<secret>\nMQTT_CA=/certs/ca.pem\nMQTT_CERT=/certs/client.pem\nMQTT_KEY=/certs/client.key'}/><p>AWS IoT 연결에는 실제 엔드포인트·인증서·정책·TLS 설정이 필요합니다. 로컬 브로커 시험을 AWS 또는 외부 운영 VPP 검증으로 간주하지 않습니다.</p><h3>운영 한계</h3><p>단일 서버 프로세스의 가상 SCADA입니다. 제조사 동특성·실물 안전 인터록·다중 사용자 권한·대규모 장기 부하는 별도 검증 범위입니다. SQLite WAL의 일관성 있는 백업과 실제 복원 실행을 함께 확인하세요.</p><p>클라이언트 VPP_CONNECT_TIMEOUT_MS는 연결 제한시간(기본 10000, 100–60000ms)입니다. COMMAND_TIMEOUT_SECONDS는 명령 실행 제한시간(기본 120, 1–3600초), 클라이언트 결과 대기는 그 값+45초입니다. 보고서 출력은 dispatch 전용입니다.</p></>}</div></Panel></>}
function Register({onClose,act,onDone,onError}){const [form,setForm]=useState({name:'',type:'wind',count:6,ratedKw:3000,rampKwPerSec:150,lat:'',lon:'',station:'',unit:'kw',semantics:'sample',csv:''}),[fileName,setFileName]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[preview,setPreview]=useState(null),[previewError,setPreviewError]=useState(''),[previewPending,setPreviewPending]=useState(false),[filePending,setFilePending]=useState(false);const previewRevision=useRef(0),previewInFlight=useRef(false),fileRevision=useRef(0);useEffect(()=>()=>{previewRevision.current++;fileRevision.current++},[]);const invalidatePreview=()=>{previewRevision.current++;setPreview(null);setPreviewError('')};const set=(k,v)=>{if(k==='csv'){fileRevision.current++;setFilePending(false)}if(['csv','type','unit','semantics'].includes(k))invalidatePreview();setForm(f=>({...f,[k]:v}))};const previewCSV=async()=>{if(previewInFlight.current||filePending)return;previewInFlight.current=true;setPreviewPending(true);setPreviewError('');setPreview(null);const revision=previewRevision.current;try{const result=await api('/datasets/preview','POST',{csv:form.csv,type:form.type,unit:form.unit,semantics:form.semantics});if(revision===previewRevision.current)setPreview(result)}catch(e){if(revision===previewRevision.current)setPreviewError(e.message)}finally{previewInFlight.current=false;setPreviewPending(false)}};return <div className="modal-backdrop"><section className="modal" role="dialog" aria-modal="true" aria-labelledby="register-title"><div className="modal-title"><div><div className="eyebrow">NEW VIRTUAL POWER PLANT</div><h2 id="register-title">RTU · 발전단지 등록</h2></div><button aria-label="등록 창 닫기" onClick={onClose}><X/></button></div><form onSubmit={async e=>{e.preventDefault();if(filePending||busy)return;setError('');setBusy(true);const data={...form};for(const k of ['lat','lon','station'])if(data[k]==='')delete data[k];try{const p=await act('/plants','POST',data,'새 RTU를 등록했습니다.');onDone(p)}catch(e){setError(e.message)}finally{setBusy(false)}}}><div className="form-grid"><Field label="단지명"><input autoFocus required maxLength="80" value={form.name} onChange={e=>set('name',e.target.value)} placeholder="예: 제주 바람 발전단지"/></Field><Field label="발전 유형"><select value={form.type} onChange={e=>set('type',e.target.value)}><option value="wind">풍력</option><option value="solar">태양광</option><option value="hybrid">복합 · 풍력+태양광</option></select></Field><Num label="발전기 수 (기)" value={form.count} onChange={v=>set('count',v)} min={form.type==='hybrid'?2:1} max="100" step="1" required/><Num label="1기 정격 (kW)" value={form.ratedKw} onChange={v=>set('ratedKw',v)} min="1" max="1000000" required/><Num label="램프 (kW/s)" value={form.rampKwPerSec} onChange={v=>set('rampKwPerSec',v)} min="0.01" max={form.ratedKw} required/><Num label="KMA 관측소 (선택)" value={form.station} onChange={v=>set('station',v)} min="1" max="9999" step="1"/><Num label="위도 (선택)" value={form.lat} onChange={v=>set('lat',v)} min="-90" max="90"/><Num label="경도 (선택)" value={form.lon} onChange={v=>set('lon',v)} min="-180" max="180"/><Field label="입력 단위"><select value={form.unit} onChange={e=>set('unit',e.target.value)}><option value="kw">kW · 출력</option><option value="kwh">kWh · 구간 에너지</option></select></Field><Field label="값 의미"><select value={form.semantics} onChange={e=>set('semantics',e.target.value)}><option value="sample">시점 샘플 · 선형 보간</option><option value="mean">구간 평균 · 구간 유지</option></select></Field></div><p className="hint">좌표는 함께 입력하거나 모두 생략하세요. 생략하면 대관령·영덕·제주·신안 중 지역 인근 가상 좌표가 지정됩니다.</p><Field label="발전 CSV / TSV 파일"><input type="file" accept=".csv,.tsv,text/csv,text/tab-separated-values" onChange={async e=>{const file=e.target.files[0];if(file){const revision=++fileRevision.current;invalidatePreview();if(file.size>20*1024*1024){setFilePending(false);setFileName('');set('csv','');setError('CSV 파일은 20MiB 이하여야 합니다.');return}setFileName(file.name);setFilePending(true);setError('');try{const csv=await file.text();if(revision===fileRevision.current){setFilePending(false);set('csv',csv)}}catch(e){if(revision===fileRevision.current){setFilePending(false);setFileName('');setError('CSV 파일을 읽지 못했습니다: '+e.message)}}}}}/></Field><Field label={fileName||'CSV 본문'} hint="필수: timestamp,power_kw · 복합 분리 출력: wind_power_kw,solar_power_kw · 선택: wind_speed_ms,wind_direction_deg,irradiance_wm2,voltage,current_a"><textarea required rows="5" value={form.csv} onChange={e=>set('csv',e.target.value)} placeholder={'timestamp,power_kw\n2026-01-01T00:00:00Z,500\n2026-01-01T00:10:00Z,900'}/></Field><div className="preview-actions"><Button type="button" disabled={previewPending||filePending||!form.csv.trim()} onClick={previewCSV}>{previewPending?<RefreshCw size={15}/>:<Telescope size={15}/>} {filePending?'CSV 파일 읽는 중…':previewPending?'CSV 해석 중…':'CSV 해석 미리보기'}</Button><small>미리보기는 RTU를 생성하지 않습니다. 실제 등록 시 서버가 다시 검증합니다.</small></div>{previewError&&<div role="alert" className="alert error">{previewError}</div>}{preview&&<DatasetPreview data={preview}/>}<div className="sample-links">샘플 다운로드 {['wind','solar','hybrid'].map(t=><button type="button" key={t} onClick={()=>download('/samples/'+t,`${t}.csv`).catch(e=>setError(e.message))}>{typeNames[t]} CSV <Download size={12}/></button>)}</div>{error&&<div role="alert" className="alert error">{error}</div>}<div className="modal-actions"><Button type="button" onClick={onClose}>취소</Button><Button kind="primary" type="submit" disabled={busy||filePending}>{busy?'등록 중…':'RTU 등록 · 수집 시작'}</Button></div></form></section></div>}

function DatasetPreview({data}){const extraColumns=[['wind_power_kw','풍력 (kW)'],['solar_power_kw','태양광 (kW)'],['wind_speed_ms','풍속 (m/s)'],['wind_direction_deg','풍향 (°)'],['irradiance_wm2','일사 (W/m²)'],['voltage','전압 (V)'],['current_a','원본 전류 (A)']].filter(([key])=>data.rows.some(row=>row[key]!=null));return <section className="dataset-preview" aria-label="CSV 해석 미리보기 결과"><div className="preview-heading"><h3>정규화 결과</h3><Badge good>{fmt(data.rowCount,0)}행 검증</Badge></div><p className="hint">{typeNames[data.type]} · 입력 {data.unit} · {data.semantics==='mean'?'구간 평균':'시점 샘플'} · {data.interpolation==='hold'?'구간 유지 (hold)':'선형 보간 (linear)'}</p><div className="preview-power"><div><small>최소 정규화 출력</small><strong>{fmt(data.minPowerKw,3)} <span>kW</span></strong></div><div><small>최대 정규화 출력</small><strong>{fmt(data.maxPowerKw,3)} <span>kW</span></strong></div></div><p className="hint">출력 기준: {data.powerSource==='wind_plus_solar'?'풍력 + 태양광 합계 (wind_power_kw + solar_power_kw)':'원본 총출력 power_kw 우선'} · {data.intervalSeconds}초 입력 간격</p><dl className="preview-times"><dt>시작 UTC</dt><dd>{data.start.utc}</dd><dt>시작 KST</dt><dd>{data.start.kst}</dd><dt>마지막 UTC</dt><dd>{data.end.utc}</dd><dt>마지막 KST</dt><dd>{data.end.kst}</dd></dl><div className="table-wrap"><table><caption>앞 {data.rows.length}개 정규화 행 · 모든 출력은 kW</caption><thead><tr><th>시각 UTC / KST</th><th>총출력</th>{extraColumns.map(([key,label])=><th key={key}>{label}</th>)}</tr></thead><tbody>{data.rows.map((row,i)=><tr key={i}><td className="mono">{row.timestamp}<small className="block">{row.timestampKst}</small></td><td>{fmt(row.totalPowerKw,3)}</td>{extraColumns.map(([key])=><td key={key}>{fmt(row[key],3)}</td>)}</tr>)}</tbody></table></div><p className="hint">파일 내용·유형·단위·값 의미를 바꾸면 이 결과가 무효화됩니다.</p></section>}
createRoot(document.getElementById('root')).render(<App/>);
